1	export type Cell = [number, number];
2	
3	const MIN_NEIGHBORS_TO_SURVIVE = 2;
4	const MAX_NEIGHBORS_TO_SURVIVE = 3;
5	const NEIGHBORS_TO_BE_BORN = 3;
6	
7	const isSameCell = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
8	  x === otherX && y === otherY;
9	
10	const isNeighborOf = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
11	  Math.abs(x - otherX) <= 1 && Math.abs(y - otherY) <= 1;
12	
13	function countLiveNeighbors(cell: Cell, liveCells: Cell[]): number {
14	  return liveCells.filter(
15	    (other) => !isSameCell(cell, other) && isNeighborOf(cell, other),
16	  ).length;
17	}
18	
19	const survives = (neighbors: number): boolean =>
20	  neighbors >= MIN_NEIGHBORS_TO_SURVIVE &&
21	  neighbors <= MAX_NEIGHBORS_TO_SURVIVE;
22	
23	const isBorn = (neighbors: number): boolean =>
24	  neighbors === NEIGHBORS_TO_BE_BORN;
25	
26	const isAlive = (cell: Cell, liveCells: Cell[]): boolean =>
27	  liveCells.some((other) => isSameCell(cell, other));
28	
29	function candidates(liveCells: Cell[]): Cell[] {
30	  const seen = new Map<string, Cell>();
31	
32	  for (const [x, y] of liveCells) {
33	    for (let dx = -1; dx <= 1; dx++) {
34	      for (let dy = -1; dy <= 1; dy++) {
35	        seen.set(`${x + dx},${y + dy}`, [x + dx, y + dy]);
36	      }
37	    }
38	  }
39	
40	  return [...seen.values()];
41	}
42	
43	export function nextGeneration(liveCells: Cell[]): Cell[] {
44	  return candidates(liveCells).filter((cell) => {
45	    const neighbors = countLiveNeighbors(cell, liveCells);
46	
47	    return isAlive(cell, liveCells) ? survives(neighbors) : isBorn(neighbors);
48	  });
49	}
