1	import { describe, it, expect } from "vitest";
2	import { nextGeneration, type Cell } from "./game-of-life.js";
3	
4	describe("Game of Life - Next Generation", () => {
5	  it("should return an empty grid for an empty grid — [] -> []", () => {
6	    expect(nextGeneration([])).toEqual([]);
7	  });
8	
9	  it("should kill a single live cell with 0 neighbors (underpopulation) — [(0,0)] -> []", () => {
10	    expect(nextGeneration([[0, 0]])).toEqual([]);
11	  });
12	
13	  it("should kill both live cells when each has only 1 neighbor (underpopulation) — [(0,1), (1,1)] -> []", () => {
14	    expect(
15	      nextGeneration([
16	        [0, 1],
17	        [1, 1],
18	      ]),
19	    ).toEqual([]);
20	  });
21	
22	  // NOTE: the spec's Rule 2 illustration (`###`/`...`/`.#.` -> `.#.`/`.#.`/`...`)
23	  // is not reproducible under Conway's rules: its centre (1,1) is dead with 4
24	  // live neighbours, and the true next generation is [(1,-1),(0,1),(1,0),(2,1)].
25	  // The spec's *statement* of Rule 2 is sound, so we test that statement using
26	  // the block, where every live cell has exactly 3 neighbours and survives.
27	  it("should keep a live cell with 3 live neighbors alive (survival) — (0,0) of the block has 3 neighbors and survives", () => {
28	    const block: Cell[] = [
29	      [0, 0],
30	      [1, 0],
31	      [0, 1],
32	      [1, 1],
33	    ];
34	
35	    expect(nextGeneration(block)).toContainEqual([0, 0]);
36	  });
37	
38	  // NOTE: as with Rule 2, the spec's Rule 3 illustration is inaccurate. In
39	  // `###`/`.#.`/`###` the centre (1,1) has 6 live neighbours, not the 4 the
40	  // prose claims, and the drawn Gen 1 (`#.#`/`#.#`/`#.#`) is not the true next
41	  // generation. The asserted *behaviour* is nonetheless correct: the centre is
42	  // overpopulated and dies, so we assert its absence rather than the drawing.
43	  it("should kill a live cell with 4 live neighbors (overpopulation) — center (1,1) of `###`/`.#.`/`###` dies", () => {
44	    const grid: Cell[] = [
45	      [0, 0],
46	      [1, 0],
47	      [2, 0],
48	      [1, 1],
49	      [0, 2],
50	      [1, 2],
51	      [2, 2],
52	    ];
53	
54	    expect(nextGeneration(grid)).not.toContainEqual([1, 1]);
55	  });
56	
57	  it("should bring a dead cell with exactly 3 live neighbors to life (reproduction) — (1,1) of `##.`/`#..`/`...` becomes alive", () => {
58	    const grid: Cell[] = [
59	      [0, 0],
60	      [1, 0],
61	      [0, 1],
62	    ];
63	
64	    expect(nextGeneration(grid)).toContainEqual([1, 1]);
65	  });
66	
67	  it.todo(
68	    "should keep a block unchanged (still life) — [(0,0), (1,0), (0,1), (1,1)] -> unchanged",
69	  );
70	
71	  it.todo(
72	    "should turn a vertical blinker horizontal — [(0,0), (0,1), (0,2)] -> [(-1,1), (0,1), (1,1)]",
73	  );
74	
75	  it.todo(
76	    "should turn the horizontal blinker back to vertical — [(-1,1), (0,1), (1,1)] -> [(0,0), (0,1), (0,2)]",
77	  );
78	
79	  it.todo(
80	    "should handle negative coordinates — a blinker at negative coordinates oscillates",
81	  );
82	});
