const OFFSETS = [-1, 0, 1];

const key = ([x, y]: Cell): string => `${x},${y}`;

const neighborsOf = ([x, y]: Cell): Cell[] =>
  OFFSETS.flatMap((dx) =>
    OFFSETS.filter((dy) => dx !== 0 || dy !== 0).map(
      (dy): Cell => [x + dx, y + dy],
    ),
  );

const countLiveNeighbors = (cell: Cell, liveCells: Set<string>): number =>
  neighborsOf(cell).filter((neighbor) => liveCells.has(key(neighbor))).length;

