const isAlive = (cell: Cell, liveCells: Cell[]): boolean =>
  liveCells.some((other) => isSameCell(cell, other));

function candidates(liveCells: Cell[]): Cell[] {
  const seen = new Map<string, Cell>();

  for (const [x, y] of liveCells) {
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        seen.set(`${x + dx},${y + dy}`, [x + dx, y + dy]);
      }
    }
  }

  return [...seen.values()];
}

export function nextGeneration(liveCells: Cell[]): Cell[] {
  return candidates(liveCells).filter((cell) => {
    const neighbors = countLiveNeighbors(cell, liveCells);

    return isAlive(cell, liveCells) ? survives(neighbors) : isBorn(neighbors);
  });
}

